mapper.select:
SELECT o.order_id, o.order_number, o.order_type, o.order_status, o.total_amount, o.discount_amount, o.ordered_at, m.member_id, m.name AS member_name, m.email AS member_email, m.phone AS member_phone, oi.order_item_id AS first_order_item_id, oi.product_name AS first_product_name, p.thumbnail_url AS first_thumbnail_url, oi.quantity AS first_item_quantity, ( SELECT COUNT(*) FROM ORDER_ITEM oi_count WHERE oi_count.order_id = o.order_id ) AS item_count, pay.payment_method, pay.payment_status, s.shipping_status, s.carrier, s.tracking_number FROM ORDERS o JOIN MEMBER m ON m.member_id = o.member_id LEFT JOIN ORDER_ITEM oi ON oi.order_item_id = ( SELECT MIN(oi_first.order_item_id) FROM ORDER_ITEM oi_first WHERE oi_first.order_id = o.order_id ) LEFT JOIN PRODUCT p ON p.product_id = oi.product_id LEFT JOIN PAYMENT pay ON pay.order_id = o.order_id LEFT JOIN SHIPPING s ON s.order_id = o.order_id
AND ( o.order_number LIKE CONCAT('%', #{keyword}, '%') OR m.email LIKE CONCAT('%', #{keyword}, '%') )
AND o.order_type = #{orderType}
AND o.order_status = #{orderStatus}
AND s.shipping_status = #{shippingStatus}
ORDER BY o.ordered_at DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM ORDERS o
JOIN MEMBER m
    ON m.member_id = o.member_id
LEFT JOIN SHIPPING s
    ON s.order_id = o.order_id


        AND (
            o.order_number LIKE CONCAT('%', #{keyword}, '%')
            OR m.email LIKE CONCAT('%', #{keyword}, '%')
        )


        AND o.order_type = #{orderType}


        AND o.order_status = #{orderStatus}


        AND s.shipping_status = #{shippingStatus}

SELECT order_status
FROM ORDERS
WHERE order_id = #{orderId}

SELECT payment_status
FROM PAYMENT
WHERE order_id = #{orderId}

mapper.update:
UPDATE ORDERS
SET order_status = #{orderStatus}
WHERE order_id = #{orderId}

UPDATE PAYMENT
SET payment_status = #{paymentStatus}
WHERE order_id = #{orderId}

UPDATE SHIPPING
SET
    carrier = #{carrier},
    tracking_number = #{trackingNumber}
WHERE order_id = #{orderId}
